#[path="../canonical-root/root.rs"]mod root;
#[path="../action-consensus/ring.rs"]mod ring;
use hec_native_ic::{counted,fp::Fp,poly::Poly,jac::Curve,instance::factor_base,rng::Rng,oracle::{split,OracleStats}};
use std::collections::BTreeSet;
fn main(){counted::disable();let(mut cells,mut trials,mut opportunities,mut no_trigger)=(0,0,0,0);for(p,cc,ell)in[(101,2,7481),(251,18,67931),(601,7,411491)]{let c=Curve::new(Fp::new(p),Poly::from_coeffs(&[cc,0,0,0,0,1]));let f=&c.fp;let z=root::power_map(f,5).0;let fb=factor_base(&c);let base=c.place(fb[0].0,fb[0].1);let mut rng=Rng::new(2026113000^p);let mut ratios=vec![];for e in 1..5{let q=f.pow(z,e);let den=f.add(1,q);assert_ne!(den,0);ratios.push((e,q,den,f.inv(den)));}let r=ring::Ring::new(ell);for e in 1..5{for sign in[1,ell-1]{let a=r.add(ring::ONE,r.scale(r.z(e as usize),sign));assert_eq!(r.mul(a,r.inv(a)),ring::ONE);}}
for sm in[1,17]{let d=c.mul(&base,sm);for case in 0..2{let k=1+rng.below(ell-1);let target=c.mul(&d,k);let mut anchor=target;let mut rows=BTreeSet::new();let(mut local_trials,mut skips)=(0,0);for ai in 1..=16{anchor=c.add(&anchor,&base);if anchor.u.deg()!=2{continue}let mut x=fb[0].0;for _ in 0..5{for y in[fb[0].1,f.neg(fb[0].1)]{let u=anchor.u.eval(x,f);if u==0{skips+=1;continue}local_trials+=1;let t=f.mul(f.sub(y,anchor.v.eval(x,f)),f.inv(u));let tt=f.mul(t,t);let h1=f.neg(f.add(tt,anchor.u.c[1]));let w1=f.add(anchor.v.c[1],f.mul(t,anchor.u.c[1]));let h2=f.neg(f.add(f.add(f.mul(f.mul(2,t),w1),f.mul(anchor.u.c[1],h1)),anchor.u.c[0]));let s=f.sub(f.add(tt,anchor.u.c[1]),x);let pp=f.sub(h2,f.mul(x,s));let qpoly=Poly::from_coeffs(&[pp,f.neg(s),1]);let w=anchor.v.add(&anchor.u.scale(t,f),f);let h=c.f.sub(&w.mul(&w,f),f).div_exact(&anchor.u,f);assert_eq!(h.div_exact(&Poly::x_minus(x,f),f),qpoly);let old=split(&qpoly,f,&mut OracleStats::default());let mut direct=BTreeSet::new();if let Some(rs)=old{if rs.len==2&&rs.r[0].1==1&&rs.r[1].1==1{let a=rs.r[0].0;let b=rs.r[1].0;for &(_,q,_,_)in &ratios{if a!=0&&f.mul(a,q)==b||b!=0&&f.mul(b,q)==a{direct.insert((a.min(b),a.max(b)));}}}}
let mut fast=BTreeSet::new();for &(e,q,den,iv)in &ratios{if s==0||f.mul(pp,f.mul(den,den))!=f.mul(q,f.mul(s,s)){continue}let a=f.mul(s,iv);let b=f.mul(q,a);assert_ne!(a,b);assert_eq!(qpoly,Poly::x_minus(a,f).mul(&Poly::x_minus(b,f),f));let ya=w.eval(a,f);let yb=w.eval(b,f);assert_eq!(f.mul(ya,ya),c.f.eval(a,f));assert_eq!(f.mul(yb,yb),c.f.eval(b,f));assert!(yb==ya||yb==f.neg(ya));let sign=if yb==ya{1}else{ell-1};let coeff=r.add(ring::ONE,r.scale(r.z(e as usize),sign));assert_eq!(r.mul(coeff,r.inv(coeff)),ring::ONE);let group=c.add_place(&c.add_place(&c.add_place(&anchor,x,y),a,ya),b,yb);assert!(c.is_zero(&group));fast.insert((a.min(b),a.max(b)));rows.insert((ai,t,x,y,a.min(b),a.max(b)));}assert_eq!(fast,direct);}x=f.mul(x,z);}}
let count=rows.len();if count==0{no_trigger+=1;}opportunities+=count;trials+=local_trials;cells+=1;println!("CELL\tp={p}\tsm={sm}\tcase={case}\ttrials={local_trials}\tu_zero_skips={skips}\tgrounding_rows={count}\trows={rows:?}");}}}assert_eq!(cells,12);eprintln!("PASS original_target_cells={cells} trials={trials} grounding_rows={opportunities} no_trigger_cells={no_trigger} recognition_matches_full_quadratic_oracle=true exact_principal_and_native_group=true unit_grounding_controls=true no_solver_or_cost_claim=true independent_verification=false");}
